-- ===========================================================================
-- Part 2: constraints and Row Level Security (hand-written)
-- ===========================================================================

-- Users need at least one sign-in identifier, stored in normalized form.
ALTER TABLE "users"
  ADD CONSTRAINT "users_identifier_present" CHECK ("email" IS NOT NULL OR "phone" IS NOT NULL),
  ADD CONSTRAINT "users_email_normalized" CHECK ("email" = lower(btrim("email"))),
  ADD CONSTRAINT "users_phone_normalized" CHECK ("phone" ~ '^\+8801[3-9][0-9]{8}$'),
  ADD CONSTRAINT "users_name_present" CHECK (length(btrim("name")) > 0);

ALTER TABLE "tenants"
  ADD CONSTRAINT "tenants_name_present" CHECK (length(btrim("name")) > 0);

-- is_default is TRUE or NULL; with the unique (tenant_id, is_default) index this
-- allows exactly one default branch per tenant.
ALTER TABLE "branches"
  ADD CONSTRAINT "branches_is_default_true_or_null" CHECK ("is_default"),
  ADD CONSTRAINT "branches_name_present" CHECK (length(btrim("name")) > 0);

-- A refresh token can never replace itself.
ALTER TABLE "refresh_tokens"
  ADD CONSTRAINT "refresh_tokens_not_self_replaced" CHECK ("replaced_by_id" <> "id");

-- RLS context. The API sets these with set_config(..., true) (transaction-local)
-- at the start of every tenant-scoped transaction. Missing context yields NULL,
-- so every policy below evaluates to false and no rows are visible: fail closed.
CREATE FUNCTION app_current_tenant_id() RETURNS uuid
  LANGUAGE sql STABLE PARALLEL SAFE
  AS $$ SELECT NULLIF(current_setting('app.tenant_id', true), '')::uuid $$;

CREATE FUNCTION app_current_user_id() RETURNS uuid
  LANGUAGE sql STABLE PARALLEL SAFE
  AS $$ SELECT NULLIF(current_setting('app.user_id', true), '')::uuid $$;

-- branches: tenant isolation for every command.
ALTER TABLE "branches" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "branches" FORCE ROW LEVEL SECURITY;
CREATE POLICY "branches_tenant_isolation" ON "branches"
  USING ("tenant_id" = app_current_tenant_id())
  WITH CHECK ("tenant_id" = app_current_tenant_id());

-- memberships: tenant isolation for every command, plus read access to the
-- current user's own memberships in other shops (for the shop switcher).
-- Permissive policies are OR'd per command, so writes still need tenant context.
ALTER TABLE "memberships" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "memberships" FORCE ROW LEVEL SECURITY;
CREATE POLICY "memberships_tenant_isolation" ON "memberships"
  USING ("tenant_id" = app_current_tenant_id())
  WITH CHECK ("tenant_id" = app_current_tenant_id());
CREATE POLICY "memberships_self_read" ON "memberships"
  FOR SELECT
  USING ("user_id" = app_current_user_id());
